    </div>'''

def section_header(anchor, title, subtitle):
    return f'''
    <div class="section-header">
      <a id="{anchor}"></a>
      <h2>{title}</h2>
      <p>{subtitle}</p>
    </div>'''

def insight_box(text, icon="💡"):
    return f'<div class="insight">{icon} {text}</div>'

def table_html(df_table, fmt_cols=None):
    rows = ""
    for _, row in df_table.iterrows():
        cells = ""
        for col in df_table.columns:
            v = row[col]
            if fmt_cols and col in fmt_cols:
                v = f"{v:{fmt_cols[col]}}"
            cells += f'<td>{v}</td>'
        rows += f'<tr>{cells}</tr>'
    headers = "".join(f'<th>{c}</th>' for c in df_table.columns)
    return f'<table class="data-table"><thead><tr>{headers}</tr></thead><tbody>{rows}</tbody></table>'

