# ── helper: SVG bar chart ──────────────────────────────────────────────────────
def svg_bar(labels, values, title, color="#3B82F6", height=220, unit="", fmt=".1f"):
    w, pad_l, pad_r, pad_t, pad_b = 560, 160, 30, 40, 50
    chart_w = w - pad_l - pad_r
    n = len(labels)
    bar_w = min(40, (chart_w / n) * 0.6)
    gap = chart_w / n
    max_v = max(abs(v) for v in values) or 1
    # allow negative
    min_v = min(values)
    y_min = min(0, min_v * 1.1)
    y_max = max_v * 1.15
    chart_h = height - pad_t - pad_b
    def ys(v):
        return pad_t + chart_h * (1 - (v - y_min) / (y_max - y_min))
    zero_y = ys(0)

    bars = ""
    xlabels = ""
    vlabels = ""
    for i, (lbl, v) in enumerate(zip(labels, values)):
        x = pad_l + i * gap + gap / 2
        y_bar = ys(v)
        bh = abs(zero_y - y_bar)
        by = min(y_bar, zero_y)
        fill = "#EF4444" if v < 0 else color
        bars += f'<rect x="{x - bar_w/2:.1f}" y="{by:.1f}" width="{bar_w:.1f}" height="{bh:.1f}" fill="{fill}" rx="3"/>'
        xlabels += f'<text x="{x:.1f}" y="{pad_t + chart_h + 18}" text-anchor="middle" font-size="11" fill="#64748b">{lbl}</text>'
        vy = y_bar - 5 if v >= 0 else y_bar + bh + 14
        vlabels += f'<text x="{x:.1f}" y="{vy:.1f}" text-anchor="middle" font-size="10" fill="#334155">{v:{fmt}}{unit}</text>'

    # y-axis ticks
    ticks = ""
    n_ticks = 5
    for i in range(n_ticks + 1):
        tv = y_min + (y_max - y_min) * i / n_ticks
        ty = ys(tv)
        ticks += f'<line x1="{pad_l - 5}" y1="{ty:.1f}" x2="{pad_l + chart_w}" y2="{ty:.1f}" stroke="#e2e8f0" stroke-width="1"/>'
        ticks += f'<text x="{pad_l - 8}" y="{ty + 4:.1f}" text-anchor="end" font-size="10" fill="#94a3b8">{tv:{fmt}}</text>'

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{height}" style="max-width:100%;height:auto">
  <text x="{w/2}" y="22" text-anchor="middle" font-size="13" font-weight="600" fill="#1e293b">{title}</text>
  {ticks}
  <line x1="{pad_l}" y1="{pad_t}" x2="{pad_l}" y2="{pad_t+chart_h}" stroke="#cbd5e1" stroke-width="1"/>
  <line x1="{pad_l}" y1="{zero_y:.1f}" x2="{pad_l+chart_w}" y2="{zero_y:.1f}" stroke="#94a3b8" stroke-width="1"/>
  {bars}{xlabels}{vlabels}
</svg>'''
    return svg

# ── helper: SVG grouped bar ────────────────────────────────────────────────────
def svg_grouped_bar(labels, series_dict, title, colors=None, height=240, unit="", fmt=".1f"):
    if colors is None:
        colors = ["#3B82F6","#10B981","#F59E0B","#EF4444","#8B5CF6"]
    w, pad_l, pad_r, pad_t, pad_b = 580, 80, 20, 50, 60
    chart_w = w - pad_l - pad_r
    chart_h = height - pad_t - pad_b
    n = len(labels)
    series = list(series_dict.items())
    ns = len(series)
    group_w = chart_w / n
    bar_w = group_w * 0.65 / ns
    all_vals = [v for _, vs in series for v in vs]
    y_min = min(0, min(all_vals) * 1.1)
    y_max = max(all_vals) * 1.15 or 1
    def ys(v):
        return pad_t + chart_h * (1 - (v - y_min)/(y_max - y_min))
    zero_y = ys(0)

    bars = ""
    for gi, lbl in enumerate(labels):
        gx = pad_l + gi * group_w + group_w / 2
        for si, (sname, vals) in enumerate(series):
            v = vals[gi]
            x = gx - (ns * bar_w)/2 + si * bar_w + bar_w/2
            y_b = ys(v); bh = abs(zero_y - y_b); by = min(y_b, zero_y)
            bars += f'<rect x="{x - bar_w/2:.1f}" y="{by:.1f}" width="{bar_w * 0.85:.1f}" height="{bh:.1f}" fill="{colors[si % len(colors)]}" rx="2" opacity="0.9"/>'

    # x labels
    xlabels = ""
    for gi, lbl in enumerate(labels):
        gx = pad_l + gi * group_w + group_w / 2
        xlabels += f'<text x="{gx:.1f}" y="{pad_t+chart_h+16}" text-anchor="middle" font-size="11" fill="#64748b">{lbl}</text>'

    # y ticks
    ticks = ""
    for i in range(6):
        tv = y_min + (y_max - y_min) * i / 5
        ty = ys(tv)
        ticks += f'<line x1="{pad_l-4}" y1="{ty:.1f}" x2="{pad_l+chart_w}" y2="{ty:.1f}" stroke="#e2e8f0"/>'
        ticks += f'<text x="{pad_l-6}" y="{ty+4:.1f}" text-anchor="end" font-size="10" fill="#94a3b8">{tv:{fmt}}</text>'

    # legend
    legend = ""
    lx = pad_l
    ly = pad_t + chart_h + 35
    for si, (sname, _) in enumerate(series):
        legend += f'<rect x="{lx + si*110}" y="{ly}" width="12" height="12" fill="{colors[si % len(colors)]}" rx="2"/>'
        legend += f'<text x="{lx + si*110 + 16}" y="{ly+10}" font-size="11" fill="#475569">{sname}</text>'

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{height}" style="max-width:100%;height:auto">
  <text x="{w/2}" y="22" text-anchor="middle" font-size="13" font-weight="600" fill="#1e293b">{title}</text>
  {ticks}
  <line x1="{pad_l}" y1="{pad_t}" x2="{pad_l}" y2="{pad_t+chart_h}" stroke="#cbd5e1"/>
  <line x1="{pad_l}" y1="{zero_y:.1f}" x2="{pad_l+chart_w}" y2="{zero_y:.1f}" stroke="#94a3b8"/>
  {bars}{xlabels}{legend}
</svg>'''
    return svg

# ── helper: SVG heatmap ────────────────────────────────────────────────────────
def svg_heatmap(pivot_df, title, color_low="#dbeafe", color_high="#1d4ed8", fmt=".2f", height=None):
    rows = pivot_df.index.tolist()
    cols = pivot_df.columns.tolist()
    cell_w, cell_h = 90, 44
    pad_l, pad_t = 110, 50
    w = pad_l + len(cols) * cell_w + 20
    h = (height or pad_t + len(rows) * cell_h + 50)

    vmin = pivot_df.values.min()
    vmax = pivot_df.values.max()
    def lerp_color(v):
        t = (v - vmin) / (vmax - vmin + 1e-9)
        # parse hex colors
        def hx(c, i): return int(c[1+i*2:3+i*2], 16)
        r = int(hx(color_low,0) + t*(hx(color_high,0)-hx(color_low,0)))
        g = int(hx(color_low,1) + t*(hx(color_high,1)-hx(color_low,1)))
        b = int(hx(color_low,2) + t*(hx(color_high,2)-hx(color_low,2)))
        return f"rgb({r},{g},{b})"
    def text_color(v):
        t = (v - vmin) / (vmax - vmin + 1e-9)
        return "#ffffff" if t > 0.6 else "#1e293b"

    cells = ""
    for ri, row in enumerate(rows):
        cells += f'<text x="{pad_l - 6}" y="{pad_t + ri*cell_h + cell_h/2 + 5:.1f}" text-anchor="end" font-size="12" fill="#475569">{row}</text>'
        for ci, col in enumerate(cols):
            v = pivot_df.loc[row, col]
            x = pad_l + ci * cell_w
            y = pad_t + ri * cell_h
            bg = lerp_color(v)
            tc = text_color(v)
            cells += f'<rect x="{x}" y="{y}" width="{cell_w-2}" height="{cell_h-2}" fill="{bg}" rx="4"/>'
            cells += f'<text x="{x+cell_w/2-1:.1f}" y="{y+cell_h/2+5:.1f}" text-anchor="middle" font-size="12" font-weight="500" fill="{tc}">{v:{fmt}}</text>'

    col_labels = ""
    for ci, col in enumerate(cols):
        x = pad_l + ci * cell_w + cell_w / 2
        col_labels += f'<text x="{x:.1f}" y="{pad_t - 8}" text-anchor="middle" font-size="12" fill="#475569">{col}</text>'

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" style="max-width:100%;height:auto">
  <text x="{w/2}" y="22" text-anchor="middle" font-size="13" font-weight="600" fill="#1e293b">{title}</text>
  {col_labels}{cells}
</svg>'''
    return svg

# ── helper: SVG horizontal bar ─────────────────────────────────────────────────
def svg_hbar(labels, values, title, color="#3B82F6", unit="", fmt=".1f"):
    bar_h, gap = 28, 6
    pad_l, pad_r, pad_t, pad_b = 130, 80, 40, 20
    n = len(labels)
    h = pad_t + n * (bar_h + gap) + pad_b
    chart_w = 500
    w = pad_l + chart_w + pad_r
    max_v = max(values) if values else 1

    bars = ""
    for i, (lbl, v) in enumerate(zip(labels, values)):
        y = pad_t + i * (bar_h + gap)
        bw = v / max_v * chart_w
        bars += f'<rect x="{pad_l}" y="{y}" width="{bw:.1f}" height="{bar_h}" fill="{color}" rx="3" opacity="0.85"/>'
        bars += f'<text x="{pad_l - 6}" y="{y + bar_h/2 + 5:.1f}" text-anchor="end" font-size="12" fill="#475569">{lbl}</text>'
        bars += f'<text x="{pad_l + bw + 5:.1f}" y="{y + bar_h/2 + 5:.1f}" font-size="11" fill="#334155">{v:{fmt}}{unit}</text>'

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" style="max-width:100%;height:auto">
  <text x="{w/2}" y="22" text-anchor="middle" font-size="13" font-weight="600" fill="#1e293b">{title}</text>
  {bars}
</svg>'''
    return svg

